/* ---------- administrative efficiency: friction reduction only ---------- */
function adminModelD2(v,w,force=false){return NS.V032D?.adminModel?.(v,w,force)||{regions:[],byTile:{}};}
function regionForTileD2(v,w,id){return adminModelD2(v,w).regions?.find(r=>(r.tiles||[]).includes(Number(id)))||null;}
function sameInstitutionD2(v,w,a,b){const model=adminModelD2(v,w),regions=model.regions;const x=regions?.find(r=>(r.tiles||[]).includes(Number(a)))||null,y=regions?.find(r=>(r.tiles||[]).includes(Number(b)))||null;return x&&y&&x.code===y.code&&x.institutionalized&&x.officeOperational?x:null;}
const logisticsD1=NS.Village.prototype.internalLogisticsCapacity;
NS.Village.prototype.internalLogisticsCapacity=function(fromId,toId,resource='food',construction=false){const q=logisticsD1.call(this,fromId,toId,resource,construction),w=this._world;if(!w||!Number.isFinite(Number(q?.cost)))return q;const r=sameInstitutionD2(this,w,fromId,toId);if(!r)return q;const eff=clampD2(r.adminEfficiency,0,100)/100,cut=.10*eff,oldCost=Number(q.cost),cost=Math.max(0,oldCost*(1-cut)),oldCap=Number(q.capacity||0),capacity=oldCap*(1+cut*.55);const s=this.v32dAdmin||(this.v32dAdmin={});s.logisticsSavedCost32D2=Number(s.logisticsSavedCost32D2||0)+Math.max(0,oldCost-cost);return{...q,cost,capacity,adminEfficiency32D2:Number(r.adminEfficiency||0),adminFrictionReduction32D2:cut};};
const maintD1=NS.Village.prototype.processBuildingMaintenance;
NS.Village.prototype.processBuildingMaintenance=function(w){const r=maintD1.call(this,w);const a=adminModelD2(this,w),s=this.v32dAdmin||(this.v32dAdmin={});for(const p of this.residents||[])for(const m of p.v25MaintenanceQueue||[]){if(m.adminAdjusted32D2)continue;const home=a.byTile?.[p.homeTileId],target=a.byTile?.[m.targetId],reg=home&&target&&home.regionCode===target.regionCode?(a.regions||[]).find(x=>x.code===home.regionCode):null;if(reg?.institutionalized&&reg.officeOperational){const eff=clampD2(reg.adminEfficiency,0,100)/100,cut=.12*eff,before=Number(m.travelOut||0)+Number(m.travelBack||0);m.travelOut=Number(m.travelOut||0)*(1-cut);m.travelBack=Number(m.travelBack||0)*(1-cut);s.maintenanceTravelSaved32D2=Number(s.maintenanceTravelSaved32D2||0)+Math.max(0,before-Number(m.travelOut||0)-Number(m.travelBack||0));m.adminAdjusted32D2=true;m.adminEfficiency32D2=reg.adminEfficiency;}}return r;};

/* ---------- Formation route / trail observation ---------- */
function routePathD2(v,w,from,to){from=Number(from);to=Number(to);if(from===to)return[from];const dist=new Map([[from,0]]),prev=new Map(),open=[[0,from]];while(open.length){open.sort((a,b)=>a[0]-b[0]);const [d,id]=open.shift();if(d!==dist.get(id))continue;if(id===to)break;for(const n of w.map.neighbors4(id)){if(n.ownerId!==v.id||!NS.TERRAIN?.[n.terrain]?.passable)continue;let step=Number(NS.TERRAIN[n.terrain]?.tradeCost||1);if((n.buildings||[]).includes('road'))step*=.65;const nd=d+step;if(nd<(dist.get(n.id)??Infinity)){dist.set(n.id,nd);prev.set(n.id,id);open.push([nd,n.id]);}}}if(!dist.has(to))return[from];const path=[to];let cur=to;while(cur!==from&&prev.has(cur)){cur=prev.get(cur);path.push(cur);}return path.reverse();}
function formationD2Rows(v,w){const s=NS.V032D?.formationSummary?.(v,w),now=calD2(w);return(s?.rows||[]).filter(x=>x.manpower>0).map(x=>{const path=routePathD2(v,w,x.f.tileId,x.f.targetTileId),remain=Math.max(0,path.length-1),next=Math.max(0,15-(now-Number(x.f.lastMoveCal||now)));return{...x,path,remainingTiles:remain,nextMoveDays:remain?next:0};});}
function drawFormationRoutesD2(ui){if(ui.mapLayer!=='military32D')return;const g=ui._mapGeom,c=ui.q('worldCanvas');if(!g||!c)return;const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=ui.world,cols=NS.NATION_COLORS||['#62a8ff','#74d69c','#ff8b91','#bd9cff'];ctx.save();ctx.lineCap='round';ctx.lineJoin='round';for(const v of w.activeVillages||[]){const col=cols[v.id%cols.length]||'#69adff';for(const row of formationD2Rows(v,w)){const f=row.f,trail=Array.isArray(f.recentTrail)?f.recentTrail.slice(-3):[];if(trail.length){ctx.strokeStyle='rgba(230,240,255,.24)';ctx.lineWidth=Math.max(2,cell*.07);ctx.setLineDash([]);ctx.beginPath();let first=true;for(const id of [...trail,Number(f.tileId)]){const t=w.map.get(id);if(!t)continue;const x=ox+(t.x+.5)*cell,y=oy+(t.y+.5)*cell;if(first){ctx.moveTo(x,y);first=false;}else ctx.lineTo(x,y);}ctx.stroke();}
   if(row.path.length>1){ctx.strokeStyle=col;ctx.globalAlpha=.62;ctx.lineWidth=Math.max(1.5,cell*.055);ctx.setLineDash([Math.max(4,cell*.18),Math.max(3,cell*.12)]);ctx.beginPath();row.path.forEach((id,i)=>{const t=w.map.get(id);if(!t)return;const x=ox+(t.x+.5)*cell,y=oy+(t.y+.5)*cell;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;const tt=w.map.get(Number(f.targetTileId));if(tt){const x=ox+(tt.x+.5)*cell,y=oy+(tt.y+.5)*cell;ctx.strokeStyle=col;ctx.lineWidth=Math.max(1.5,cell*.05);ctx.beginPath();ctx.arc(x,y,Math.max(4,cell*.17),0,Math.PI*2);ctx.stroke();ctx.fillStyle=col;ctx.font=`700 ${Math.max(8,Math.min(12,cell*.23))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('◎',x,y);}}}}
 ctx.restore();const leg=ui.q('v15LayerLegend');if(leg)leg.textContent='군사 · ■ Garrison / ▲ Formation · 점선=예정 경로 · 흐린 선=최근 이동 3칸 · ◎ 목표 · 15일/칸 · 전투 비활성';}

/* ---------- UI ---------- */
if(NS.UI){const mapPrev=NS.UI.prototype.renderMap,tilePrev=NS.UI.prototype.renderTile,contentPrev=NS.UI.prototype.renderVillageContent,codexPrev=NS.UI.prototype.renderCodex,headPrev=NS.UI.prototype.renderHeader;
 NS.UI.prototype.renderHeader=function(){headPrev.call(this);document.title='Village Observer V0.32D2';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.32D2</strong>';const st=this.q('runtimeStatus');if(st)st.textContent='✓ V0.32D2 행정권 제도화·효율 · Formation 경로 관측 · 백과/패치노트 마감';};
 NS.UI.prototype.renderMap=function(){const requested=this.mapLayer||'base';if(requested==='admin30'){const keep=this.mapLayer;this.mapLayer='base';mapPrev.call(this);this.mapLayer=keep;const g=this._mapGeom,c=this.q('worldCanvas');if(g&&c){const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=this.world;ctx.save();for(const v of w.activeVillages||[]){for(const r of adminModelD2(v,w).regions||[]){const hue=(v.id*57+Math.max(0,'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.indexOf(String(r.code||'A')[0]))*47+28)%360;for(const id of r.tiles||[]){const t=w.map.get(id);if(!t)continue;ctx.fillStyle=r.status==='provisional'?`hsla(${hue},35%,55%,.12)`:`hsla(${hue},70%,55%,.24)`;ctx.fillRect(ox+t.x*cell,oy+t.y*cell,cell,cell);}const h=w.map.get(r.hubTileId);if(h){const x=ox+(h.x+.5)*cell,y=oy+(h.y+.5)*cell,rad=Math.max(5,cell*.23);ctx.fillStyle='rgba(10,22,37,.9)';ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fill();ctx.strokeStyle=r.institutionalized?'#ffd27a':`hsla(${hue},82%,70%,.95)`;ctx.lineWidth=Math.max(2,cell*.07);ctx.stroke();ctx.fillStyle='#fff';ctx.font=`700 ${Math.max(9,Math.min(13,cell*.28))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(r.code,x,y);if(r.institutionalized&&r.code!=='A'){ctx.font=`${Math.max(7,Math.min(10,cell*.19))}px system-ui`;ctx.fillText('🏛️',x,y+rad+Math.max(6,cell*.13));}}}}ctx.restore();}const leg=this.q('v15LayerLegend');if(leg)leg.textContent='행정권 · · = 임시 후보 / A·B·C… = 정식 권역 / 금색 테두리 = 행정청으로 제도화 · 정식 코드는 재사용하지 않음';return;}mapPrev.call(this);if(requested==='military32D')drawFormationRoutesD2(this);};
 NS.UI.prototype.renderTile=function(){tilePrev.call(this);const t=this.world.map.get(this.world.selectedTileId),root=this.q('tileInspector');if(!t||!root)return;if(t.ownerId!=null){const v=this.world.villages[t.ownerId],ad=adminModelD2(v,this.world).byTile?.[t.id];if(ad){const reg=adminModelD2(v,this.world).regions?.find(r=>r.code===ad.regionCode);root.insertAdjacentHTML('beforeend',`<div class="v32d2-admin-detail"><strong>행정 상태 · ${ad.regionCode==='·'?'임시 후보':ad.regionCode+' 행정권'}</strong><div class="small muted">${reg?.institutionalized?'제도화됨 · ':reg?.status==='formal'?'정식 권역 · ':'임시 권역 · '}행정 효율 ${Number(reg?.adminEfficiency||0).toFixed(0)}% · 행정청 ${reg?.officeOperational?'운영':'없음'}</div></div>`);}}for(const v of this.world.activeVillages||[])for(const row of formationD2Rows(v,this.world))if(Number(row.f.tileId)===Number(t.id))root.insertAdjacentHTML('beforeend',`<div class="v32d2-form-detail"><strong>이동 관측 · ${row.f.name}</strong><div class="small muted">임무 ${row.f.targetReason||'POSITION'} · 목표까지 ${row.remainingTiles}칸 · 다음 이동 약 ${row.nextMoveDays.toFixed(0)}일 · 누적 ${row.f.moveCount}칸</div></div>`);};
 NS.UI.prototype.renderVillageContent=function(){contentPrev.call(this);const v=this.world.selectedNation,root=this.q('villageContent');if(!v||!root)return;if(this.sub==='economy'){const a=adminModelD2(v,this.world),host=root.querySelector('.v32d-admin-box')||root;let box=root.querySelector('.v32d2-admin');if(box)box.remove();box=document.createElement('div');box.className='v32d2-admin';box.innerHTML=`<div class="section-head"><div><strong>🏛️ 행정권 V1.2</strong><div class="small muted">임시 후보 → 1년 유지 시 정식 코드 → 6년 유지·행정청 완공 시 제도화. 보너스는 생산량이 아니라 행정 마찰 감소입니다.</div></div></div><div class="v32d-admin-list">${(a.regions||[]).map(r=>`<span><b>${r.code}</b> ${r.code==='·'?'임시 행정권':r.label} · ${r.status==='central'?'중앙':r.institutionalized?'제도화':r.status==='formal'?'정식':'임시'} · 중심 #${r.hubTileId} · 인구 ${r.population} · 평균 경로 ${Number(r.avgCenterCost||0).toFixed(1)} · 효율 <b>${Number(r.adminEfficiency||0).toFixed(0)}%</b> · 행정청 ${r.officeOperational?'#'+r.officeTileId:'-'}</span>`).join('')}</div><div class="small muted" style="margin-top:7px">누적 행정 절감 · 내부 물류 경로비 ${Number(v.v32dAdmin?.logisticsSavedCost32D2||0).toFixed(1)} · 원격 유지보수 이동일 ${Number(v.v32dAdmin?.maintenanceTravelSaved32D2||0).toFixed(1)}</div>`;host.insertAdjacentElement('afterend',box);}if(this.sub==='military'){const host=root.querySelector('.v32d-formations');if(host){for(const row of formationD2Rows(v,this.world)){const card=[...host.querySelectorAll('.v32d-form-card')].find(x=>x.textContent.includes(row.f.name));if(card&&!card.querySelector('.v32d2-route'))card.insertAdjacentHTML('beforeend',`<div class="small muted v32d2-route">경로 ${row.path.length?row.path.join(' → '):'-'} · 남은 ${row.remainingTiles}칸 · 다음 이동 약 ${row.nextMoveDays.toFixed(0)}일 · 임무 ${row.f.targetReason||'POSITION'}</div>`);}}}};
 NS.UI.prototype.renderCodex=function(){codexPrev.call(this);const el=this.q('codexContent');if(!el)return;let box=el.querySelector('.v32d2-labor-box');if(box)box.remove();box=document.createElement('div');box.className='codex-note v32d2-labor-box';box.innerHTML='<strong>V0.32D2 철산업·군사시설 명칭/노동량</strong><br>고대 철광산 · 고대 제련소 · 고대 대장간 · 고대 병영 · 고대 훈련장 · 고대 무기고는 모두 기본 <b>600 adult-day</b>가 명시 기준입니다. 공공사업 등 기술 효과가 있으면 실제 프로젝트 노동량은 감소할 수 있습니다.';const build=el.querySelector('[data-page="build"]')||el;build.insertAdjacentElement('afterbegin',box);};
}

/* ---------- patch notes: render latest data when button opens ---------- */
function patchNotesHTMLD2(){const notes=Array.isArray(NS.PATCH_NOTES)?NS.PATCH_NOTES:[];return `<div class="patch-notes-head"><div><div class="small muted">Village Observer</div><h2 id="patchNotesTitle">패치 노트</h2></div><span class="tag">${notes[0]?.version||'V0.32D2'}</span></div><div class="small muted patch-notes-intro">README는 상세 기술 문서이며, 이 화면은 실제 플레이에 영향을 주는 변경을 버전별로 요약합니다.</div><div class="patch-notes-list">${notes.map((n,i)=>`<details class="patch-note-entry" ${i===0?'open':''}><summary><span><strong>${n.version}</strong> · ${n.title}</span><small>${n.date}</small></summary><div class="patch-note-body"><p>${n.summary}</p>${(n.sections||[]).map(([label,items])=>`<section><h3>${label}</h3><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul></section>`).join('')}</div></details>`).join('')}</div>`;}
function installPatchNotesD2(){if(typeof document==='undefined')return;let modal=document.getElementById('patchNotesModal');if(!modal){modal=document.createElement('div');modal.id='patchNotesModal';modal.className='modal patch-notes-modal';modal.innerHTML='<div class="modal-card patch-notes-card"><button type="button" class="modal-close" id="patchNotesClose">✕</button><div id="patchNotesBody"></div></div>';document.body.appendChild(modal);}const badge=document.getElementById('versionBadge'),body=document.getElementById('patchNotesBody'),close=document.getElementById('patchNotesClose');const shut=()=>{modal.classList.remove('open');badge?.setAttribute('aria-expanded','false');};const open=()=>{if(body){body.innerHTML=patchNotesHTMLD2();body.dataset.ready='dynamic32D2';}modal.classList.add('open');badge?.setAttribute('aria-expanded','true');requestAnimationFrame(()=>close?.focus());};if(badge){badge.onclick=open;badge.dataset.patchBound='d2';}if(close){close.onclick=shut;close.dataset.patchBound='d2';}if(!modal.dataset.d2Bound){modal.dataset.d2Bound='1';modal.addEventListener('click',e=>{if(e.target===modal)shut();});}if(body)body.innerHTML=patchNotesHTMLD2();}

/* ---------- telemetry ---------- */
function adminD2Summary(v,w){const a=adminModelD2(v,w),regs=a.regions||[],inst=regs.filter(r=>r.institutionalized).length,formal=regs.filter(r=>r.code!=='·').length,provisional=regs.filter(r=>r.code==='·').length,weighted=regs.reduce((x,r)=>x+Number(r.adminEfficiency||0)*Math.max(1,Number(r.population||0)),0),pop=regs.reduce((x,r)=>x+Math.max(1,Number(r.population||0)),0);return{adminFormalRegions32D2:formal,adminProvisionalRegions32D2:provisional,adminInstitutionalizedRegions32D2:inst,adminEfficiencyAvg32D2:pop?+(weighted/pop).toFixed(2):0,adminLogisticsSavedCost32D2:+Number(v.v32dAdmin?.logisticsSavedCost32D2||0).toFixed(2),adminMaintenanceTravelSaved32D2:+Number(v.v32dAdmin?.maintenanceTravelSaved32D2||0).toFixed(2),adminFormalizations32D2:Number(v.v32dAdmin?.formalizations32D2||0),adminInstitutionalizations32D2:Number(v.v32dAdmin?.institutionalizations32D2||0),adminCenterMoves32D2:Number(v.v32dAdmin?.centerMoves32D2||0),adminRetirements32D2:Number(v.v32dAdmin?.retirements32D2||0)};}
const snapD1=NS.Telemetry.prototype.snapshot;
NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snapD1.call(this,w,reason,note);if(!s)return s;const total={adminFormalRegions32D2:0,adminProvisionalRegions32D2:0,adminInstitutionalizedRegions32D2:0,adminEfficiencyAvg32D2:0,adminLogisticsSavedCost32D2:0,adminMaintenanceTravelSaved32D2:0,adminFormalizations32D2:0,adminInstitutionalizations32D2:0,adminCenterMoves32D2:0,adminRetirements32D2:0,formationRouteRemaining32D2:0,formationTrailTiles32D2:0};let effW=0,effP=0;for(const row of s.villages||[]){const v=w.villages.find(x=>Number(x.id)===Number(row.id));if(!v)continue;const a=adminD2Summary(v,w),fr=formationD2Rows(v,w),x={...a,formationRouteRemaining32D2:fr.reduce((q,z)=>q+z.remainingTiles,0),formationTrailTiles32D2:fr.reduce((q,z)=>q+(z.f.recentTrail?.length||0),0)};Object.assign(row,x);for(const k of Object.keys(total))if(k!=='adminEfficiencyAvg32D2')total[k]+=Number(x[k]||0);const pp=Math.max(1,Number(row.population||0));effW+=Number(a.adminEfficiencyAvg32D2||0)*pp;effP+=pp;}total.adminEfficiencyAvg32D2=effP?+(effW/effP).toFixed(2):0;Object.assign(s.global,total);const ys=(this.yearlySummaries||[]).find(x=>Number(x.year)===Number(w.year));if(ys){Object.assign(ys.global,total);for(const n of ys.nations||[]){const r=s.villages.find(x=>Number(x.id)===Number(n.id));if(r)Object.assign(n,r);}}return s;};
const csvD1=NS.Telemetry.prototype.snapshotsCSV;
NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvD1.call(this),lines=base.split('\n');if(!lines.length)return base;const extra=['adminFormalRegions32D2','adminProvisionalRegions32D2','adminInstitutionalizedRegions32D2','adminEfficiencyAvg32D2','adminLogisticsSavedCost32D2','adminMaintenanceTravelSaved32D2','adminFormalizations32D2','adminInstitutionalizations32D2','adminCenterMoves32D2','adminRetirements32D2','formationRouteRemaining32D2','formationTrailTiles32D2'],esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+extra.map(esc).join(',');let i=1;for(const s of this.snapshots||[])for(const v of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+extra.map(k=>esc(v[k]??s.global?.[k])).join(',');}return lines.join('\n');};
const jsonD1=NS.Telemetry.prototype.toJSON;
NS.Telemetry.prototype.toJSON=function(w){const d=jsonD1.call(this,w);d.version='0.32D2';Object.assign(d.worldSummary,{v32D2Revision:REV32D2,administration32D2:'provisional center -> 1y formal region -> 6y office -> institutionalized region; established regions resist short-term churn',administrativeEfficiency32D2:'institutionalized regions reduce internal logistics distance friction and remote-maintenance travel loss without creating resources',formationObservation32D2:'military layer shows planned route, recent 3-tile trail, target and next-move timing while movement remains 15 calendar days per adjacent tile',codexLabor32D2:'ancient iron mine/smelter/smithy/barracks/training ground/armory explicitly use 600 adult-days before technology modifiers',patchNotes32D2:'version button rebuilds patch-note DOM from current NS.PATCH_NOTES when opened'});return d;};

/* ---------- save / migration ---------- */
const serD1=NS.World.prototype.serialize,fromD1=NS.World.from;
NS.World.prototype.serialize=function(){const d=serD1.call(this);d.version='0.32D2';d.v32d2={revision:REV32D2,provisionalAdminDays:360,institutionalAdminDays:2160,centerMoveHysteresisDays:1440,adminEfficiency:true,formationRouteVisualization:true,explicitLabor:LABOR32D2,combat:false};return d;};
function attachD2(w){w=NS.V032D1?.attachWorld?.(w)||w;if(!w)return w;for(const v of w.villages||[]){v._world=w;NS.V032D?.adminModel?.(v,w,true);NS.V032D?.ensureFormations?.(v,w);}return w;}
NS.World.from=function(d){if(d?.version==='0.32D2')return attachD2(fromD1({...d,version:'0.32D1'}));return attachD2(fromD1(d));};
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.32D2'))NS.PATCH_NOTES.unshift({version:'V0.32D2',date:'2026-09-26',title:'행정 제도화·효율 · Formation 이동 관측 · 정보 UI 마감',summary:'D1 장기주행에서 확인된 행정권 코드 churn과 행정청 중복, Formation 이동의 순간이동처럼 보이는 관측 문제, 신규 시설 백과/패치노트 누락을 마감합니다. 전투는 아직 추가하지 않습니다.',sections:[['행정권 제도화',['새 비수도 행정 중심지는 즉시 알파벳을 소비하지 않고 약 1년간 임시 행정권으로 관찰한 뒤 유지되면 정식 B/C/D… 코드를 받습니다. 기존 세이브의 A/H/I 같은 이미 발급된 코드는 그대로 보존합니다.','정식 행정권이 6년 유지되고 고대 행정청이 완공되면 제도화됩니다. 제도화된 권역은 단기 인구·중심 점수 변화로 폐지되지 않으며, 중심 이동은 상당한 점수 우위가 약 4년 지속되어야 허용합니다.','행정청은 타일이 아니라 행정권 코드에 귀속됩니다. 중심지가 인근으로 이동해도 기존 관청을 인정하며 같은 권역에 행정청을 반복 건설하지 않습니다.']],['행정 효율',['제도화된 행정권은 자원을 생성하거나 생산량을 직접 올리지 않습니다. 대신 같은 권역 내부 물류의 거리 마찰을 최대 약 10% 완화합니다.','원격 유지보수 임무의 왕복 이동 손실을 행정효율에 따라 최대 약 12% 줄입니다.','행정 효율은 권역 인구·Settlement 수·중심까지 평균 경로가 커질수록 낮아져, 국가가 성장하면 새로운 행정권 분할 필요성이 자연스럽게 커집니다.']],['Formation 관측',['Formation의 실제 이동 속도는 기존과 동일하게 약 15일마다 인접 자국 타일 1칸입니다.','군사 지도에 현재 위치부터 목표까지 예정 경로를 점선으로, 최근 지나온 최대 3타일을 희미한 흔적으로, 목표를 ◎로 표시합니다.','군사 카드와 타일 상세에 남은 경로 칸 수·다음 이동까지 남은 날짜·현재 임무를 표시합니다.']],['백과·명칭',['철광산·제련소·대장간을 고대 철광산·고대 제련소·고대 대장간으로 통일합니다.','고대 철광산·고대 제련소·고대 대장간·고대 병영·고대 훈련장·고대 무기고의 기본 노동량을 600 adult-day로 기준표에 명시하고 백과에 표시합니다.','공공사업 같은 기술 효과가 적용되면 실제 공사 노동량은 기준보다 줄어들 수 있습니다.']],['패치노트·관측',['좌상단 버전 버튼을 열 때 최신 NS.PATCH_NOTES에서 내용을 다시 생성하도록 바꿔 C 이후 패치가 보이지 않던 초기 DOM 고정 문제를 제거합니다.','행정권 정식화·제도화·중심 이전·폐지 이벤트와 평균 행정효율, 물류/유지보수 절감량, Formation 잔여 경로를 Snapshot·CSV·Devlog에 추가합니다.']]]});
(function(){const KEY='village-observer-v0-32d2',fallback=['village-observer-v0-32d1','village-observer-v0-32d','village-observer-v0-32c2','village-observer-v0-32c1a','village-observer-v0-32c1','village-observer-v0-32c','village-observer-v0-32b','village-observer-v0-32a','village-observer-v0-31i','village-observer-v0-31h','village-observer-v0-31g','village-observer-v0-31f','village-observer-v0-31a','village-observer-v0-31'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v032D2-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v032D2-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v032D2-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachD2(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();
